package local.velo.bridge;
import android.app.*;import android.content.*;import android.os.*;import android.location.*;import android.net.Uri;import java.io.*;import java.util.zip.*;import org.json.*;
public class RideUiTest extends Instrumentation {
 static class TickService extends RideService {void attach(Context c){attachBaseContext(c);}}
 int count;void check(boolean value,String label)throws Exception{count++;if(!value)throw new Exception(label);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 Location fix(double lat,double lon,float acc,long time){Location p=new Location("gps");p.setLatitude(lat);p.setLongitude(lon);p.setAccuracy(acc);p.setSpeed(4);p.setBearing(90);p.setElapsedRealtimeNanos(time*1000000);return p;}
 public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();try{
  startActivitySync(new Intent().setClassName("local.velo.bridge","local.velo.bridge.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1000);
  RideService filter=new RideService();long now=SystemClock.elapsedRealtime();Location first=fix(35,139,5,now);filter.onLocationChanged(first);check(filter.latest!=null,"valid GPS accepted");filter.onLocationChanged(fix(35.01,139.01,5,now+500));check(filter.latest.getLatitude()==35,"single GPS teleport rejected");filter.onLocationChanged(fix(35.00001,139,40,now+600));check(filter.latest.getAccuracy()==5,"inaccurate fix rejected");filter.onLocationChanged(fix(35.00001,139,5,now-6000));check(filter.latest.getLatitude()==35,"stale GPS rejected");
  TickService parked=new TickService();parked.attach(c);parked.onCreate();c.getSharedPreferences("navigation",0).edit().putBoolean("board_roads",false).commit();try{
   RouteModel actual=new RouteModel("stationary test",java.util.Arrays.asList(new double[]{35,139},new double[]{35.001,139}));RouteStore.set(actual,false);parked.started=SystemClock.elapsedRealtime()-10000;long base=SystemClock.elapsedRealtime()-2000;
   for(int i=0;i<3;i++){Location still=fix(35,139,5,base+i*1000);still.setSpeed(0);parked.latest=still;parked.tick();}
   check(RideService.previewFix.phase==9,"parked with valid GPS asks for motion rather than GPS repair");check(parked.matched.phase!=9&&parked.matched.meters>=0,"presentation preserves matcher maneuver");check(parked.frame.text.contains("D,0.0,")&&parked.frame.text.contains(",9,5\n"),"GPS and zero speed reach wire consistently");
   parked.tripMeters=1240;parked.latest=null;parked.tick();check(parked.frame.text.contains("D,-1.0,1.240,")&&parked.frame.text.contains("GPSWAIT"),"GPS loss preserves trip while speed is unknown");
  }finally{parked.nearby.close();parked.warnings.close();c.getSharedPreferences("navigation",0).edit().putBoolean("board_roads",true).commit();}
  NearbyRoads nearby=new NearbyRoads(c);try{RouteModel area=new RouteModel("road network test",java.util.Arrays.asList(new double[]{33.551833,133.507556},new double[]{33.554,133.507556}));nearby.update(area,area.at(0));long deadline=SystemClock.elapsedRealtime()+35000;while(nearby.busy&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(100);check(nearby.roads!=null&&nearby.roads.edges.size()>100,"real nearby roads on Android: "+nearby.status+" "+nearby.lastError);check(!nearby.packet(area,area.at(0),9).equals("B,9,0\n"),"nearby roads transmitted");c.getSharedPreferences("navigation",0).edit().putBoolean("board_roads",false).commit();check(nearby.packet(area,area.at(0),9).equals("B,9,0\n"),"roads setting clears packet");c.getSharedPreferences("navigation",0).edit().putBoolean("board_roads",true).commit();}finally{nearby.close();}
  runOnMainSync(()->{RouteStore.set(RouteModel.demo(),true);c.startForegroundService(new Intent(c,RideService.class).putExtra("address","00:00:00:00:00:00"));});Thread.sleep(5500);
  check(RideService.running,"ride service running");check(RideService.previewFix!=null,"navigation runs without Bluetooth");check(RideService.previewFix.phase>=0,"guidance phase computed");RideLog active=RideService.activeLog;check(active!=null,"local log started");active.flush();File archive=RideLog.export(c);check(archive.isFile()&&archive.length()>0,"diagnostic ZIP created");
  int rows=0;boolean simulated=false,geometry=false;try(ZipFile zip=new ZipFile(archive);BufferedReader reader=new BufferedReader(new InputStreamReader(zip.getInputStream(zip.getEntry("diagnostics.jsonl")),"UTF-8"))){String line;while((line=reader.readLine())!=null){JSONObject o=new JSONObject(line);rows++;if("navigation".equals(o.optString("event"))&&o.optBoolean("replay"))simulated=true;if("route".equals(o.optString("event"))&&o.has("coordinates_lat_lon"))geometry=true;}check(zip.getEntry("说明.txt")!=null,"privacy and format notes included");}
  check(rows>=4&&simulated&&geometry,"structured log contains replay navigation and route geometry");Uri uri=Uri.parse("content://local.velo.bridge.diagnostics/"+archive.getName());try(InputStream in=c.getContentResolver().openInputStream(uri)){check(in.read()>=0,"read-only share URI can be opened");}
  boolean denied=false;try{c.getContentResolver().openFileDescriptor(uri,"w");}catch(FileNotFoundException e){denied=true;}check(denied,"share URI denies write access");denied=false;try{c.getContentResolver().openInputStream(Uri.parse("content://local.velo.bridge.diagnostics/../../shared_prefs/navigation.xml"));}catch(FileNotFoundException e){denied=true;}check(denied,"share URI rejects other files");
  runOnMainSync(()->c.stopService(new Intent(c,RideService.class)));Thread.sleep(700);check(!RideService.running,"ride stops");check(RideService.activeLog==null,"active logger cleared");
  result.putString("checks",count+" Android service, GPS filter, log/export and provider checks passed; rows="+rows);finish(Activity.RESULT_OK,result);
 }catch(Throwable e){c.stopService(new Intent(c,RideService.class));result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}}
}
